// Step 1: Read the article data that SharedSpace sends into n8n.
// These fields come from the write/edit article form, so the rest of the workflow can use one clean payload.
const payload = $json.body ?? $json;

const title = String(payload.title || '').trim();
const excerpt = String(payload.excerpt || '').trim();
const content = String(payload.content || '').trim();
const category = String(payload.category || '').trim();
const sourceUrl = String(payload.source_url || '').trim();
const requestedBy = payload.requested_by || {};


// This helper checks whether the reference link is from one of our Tier 1 sources.
// If the user pasted an exact Straits Times/CNA/Reuters article link, we treat it as the main evidence anchor.
const trustedSourceName = (url) => {
  const value = String(url || '').toLowerCase();
  if (value.includes('reuters.com')) return 'Reuters';
  if (value.includes('cna.com') || value.includes('channelnewsasia.com')) return 'CNA';
  if (value.includes('straitstimes.com')) return 'The Straits Times';
  return '';
};

const trustedName = trustedSourceName(sourceUrl);
const primarySource = trustedName
  ? {
      name: trustedName,
      tier: 1,
      title: title || trustedName,
      url: sourceUrl,
      snippet: excerpt || content.slice(0, 280),
      match_type: 'direct',
      relevance_note: 'primary_source_from_user_reference'
    }
  : null;


// Build one plain-text version of the article so the AI model sees the same structure every time.
// This helps reduce inconsistent results caused by messy or missing fields.
const articleText = [
  `Title: ${title || '[empty]'}`,
  `Category: ${category || '[empty]'}`,
  `Summary: ${excerpt || '[empty]'}`,
  `Reference URL: ${sourceUrl || '[none]'}`,
  'Content:',
  content || '[empty]'
].join('\n');


// This prompt is only for finding evidence. It does not score the article yet.
// Keeping search and scoring separate makes the workflow easier to explain and debug.
const searchPrompt = [
  'You are helping SharedSpace verify a user-submitted article draft using live trusted news sources.',
  'Search only these Tier 1 sources: Reuters, CNA, and The Straits Times.',
  'Find articles that directly support, partially support, contradict, or are strongly related to the draft headline and core claims.',
  trustedName ? `The user provided a trusted Tier 1 reference URL from ${trustedName}. Treat it as the primary source anchor and find any extra corroborating or contradicting sources.` : '',
  '',
  'Return ONLY valid JSON with this exact shape:',
  '{',
  '  "search_summary": "",',
  '  "matched_sources": [',
  '    {',
  '      "name": "Reuters | CNA | The Straits Times",',
  '      "tier": 1,',
  '      "title": "",',
  '      "url": "",',
  '      "snippet": "",',
  '      "match_type": "direct | related | partial | contradicts",',
  '      "relevance_note": ""',
  '    }',
  '  ]',
  '}',
  '',
  'Rules:',
  '- Return max 5 matched sources total across all domains.',
  '- Prefer direct matches over broad related stories.',
  '- Do not invent URLs, titles, or source names.',
  '- If no strong source is found, return an empty matched_sources array.',
  '- Allowed domains: reuters.com, cna.com, channelnewsasia.com, straitstimes.com.',
  '',
  'Article draft:',
  articleText
].filter(Boolean).join('\n');

return [{
  json: {
    title,
    excerpt,
    content,
    category,
    source_url: sourceUrl,
    requested_by: requestedBy,
    primary_source: primarySource,
    article_text: articleText,
    search_prompt: searchPrompt
  }
}];

// Step 2: Build the OpenAI web-search request.
// The search is restricted to our trusted domains so random blogs/social posts do not affect the score.
const searchRequest = {
  model: 'gpt-5-mini',
  reasoning: { effort: 'low' },
  tools: [
    {
      type: 'web_search',
      filters: {
        allowed_domains: [
          'reuters.com',
          'www.reuters.com',
          'cna.com',
          'www.cna.com',
          'channelnewsasia.com',
          'www.channelnewsasia.com',
          'straitstimes.com',
          'www.straitstimes.com'
        ]
      }
    }
  ],
  tool_choice: 'auto',

  // The schema forces the search step to return predictable JSON instead of free-form text.
  // That makes the next node easier to parse reliably.
text: {
    format: {
      type: 'json_schema',
      name: 'sharedspace_live_source_search',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          search_summary: { type: 'string' },
          matched_sources: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              properties: {
                name: { type: 'string' },
                tier: { type: 'integer' },
                title: { type: 'string' },
                url: { type: 'string' },
                snippet: { type: 'string' },
                match_type: { type: 'string' },
                relevance_note: { type: 'string' }
              },
              required: ['name', 'tier', 'title', 'url', 'snippet', 'match_type', 'relevance_note']
            }
          }
        },
        required: ['search_summary', 'matched_sources']
      }
    }
  },
  input: [
    {
      role: 'system',
      content: 'Return JSON only. Search Reuters, CNA, and The Straits Times for live source evidence matching the user draft. Do not score the article in this step.'
    },
    {
      role: 'user',
      content: $json.search_prompt
    }
  ]
};

return [{ json: { ...$json, search_request: searchRequest } }];

// Step 3: Parse the search result returned by OpenAI.
// OpenAI returns the JSON as text, so we clean and parse it safely before using it.
const raw = $json.output_text || $json.output?.find((item) => item.type === 'message')?.content?.find((part) => part.type === 'output_text')?.text || '{}';
const cleaned = String(raw).replace(/```json|```/gi, '').trim();
let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = { search_summary: 'Search response could not be parsed.', matched_sources: [] };
}


// n8n returns previous-node items as an array, so [0].json is needed here.
// Without this, the workflow may lose the original article text after the HTTP request.
const upstream = $items('Build Search Request', 0, 0)?.[0]?.json || {};
const allowedNames = ['Reuters', 'CNA', 'The Straits Times'];

// Normalize source names so variants like "Channel NewsAsia" and "CNA" count as the same source.
// This keeps Source Quality scoring consistent.
const normalizeName = (name, url) => {
  const value = String(name || '').toLowerCase();
  const link = String(url || '').toLowerCase();
  if (value.includes('reuters') || link.includes('reuters.com')) return 'Reuters';
  if (value.includes('cna') || value.includes('channel newsasia') || link.includes('cna.com') || link.includes('channelnewsasia.com')) return 'CNA';
  if (value.includes('straits') || link.includes('straitstimes.com')) return 'The Straits Times';
  return String(name || 'Unknown');
};

const normalizeSource = (source) => {
  const name = normalizeName(source.name, source.url);
  return {
    name,
    tier: allowedNames.includes(name) ? 1 : Number(source.tier || 2),
    title: String(source.title || ''),
    url: String(source.url || ''),
    snippet: String(source.snippet || ''),
    match_type: String(source.match_type || 'related').toLowerCase(),
    relevance_note: String(source.relevance_note || '')
  };
};

const searchSources = Array.isArray(parsed.matched_sources)
  ? parsed.matched_sources.slice(0, 5).map(normalizeSource).filter((source) => source.title || source.url || source.snippet)
  : [];


// Start with the user's exact trusted reference link, then add any extra sources found by search.
// This prevents the workflow from ignoring a valid Straits Times/CNA/Reuters URL pasted by the writer.
const allSources = [];
if (upstream.primary_source) {
  allSources.push(normalizeSource(upstream.primary_source));
}
for (const source of searchSources) {
  const key = `${source.name}|${source.url}`.toLowerCase();
  if (!allSources.some((item) => `${item.name}|${item.url}`.toLowerCase() === key)) {
    allSources.push(source);
  }
}

const matchedSources = allSources.slice(0, 5);

return [{
  json: {
    ...upstream,
    search_summary: String(parsed.search_summary || ''),
    matched_sources: matchedSources,
    matched_articles: matchedSources.map((source) => ({
      title: source.title,
      url: source.url,
      relevance_note: source.relevance_note
    }))
  }
}];

// Step 4: Build the marking prompt using our SharedSpace rubric.
// The AI gives structured category notes, but the final node recalculates key scores in code for consistency.
const matchedSources = Array.isArray($json.matched_sources) ? $json.matched_sources : [];
const matchedSourcesJson = JSON.stringify(matchedSources, null, 2);


// Rubric overview for presentation:
// A = Factual Accuracy (35), S = Source Quality (20), B = Bias/Neutrality (20),
// L = Logical Consistency (15), C = Completeness (10). Total = 100.
const rubricPrompt = [
  'You are a strict news verification AI for SharedSpace. Score the article using the rubric exactly as specified.',
  'Return ONLY valid JSON matching the schema. Do not add commentary outside the JSON.',
  '',
  'RUBRIC:',
  'Trust Score = A + S + B + L + C. The category maximums already encode the weights: A 35, S 20, B 20, L 15, C 10.',
  'A = Factual Accuracy, max 35. Bands: 30-35 all verifiable claims confirmed by Tier 1; 20-29 most claims confirmed with <=2 minor unconfirmed details; 10-19 core claim confirmed but factual error or key contradiction exists; 0-9 core claim unverifiable, contradicted, or fabricated.',
  'S = Source Quality, max 20. Bands: 17-20 if >=2 distinct Tier 1 sources directly confirm or relate; 12-16 if exactly 1 Tier 1 source matches; 6-11 if only Tier 2 or tangential Tier 1; 0-5 if no Tier 1/Tier 2 match.',
  'B = Bias/Neutrality, max 20. Bands: 17-20 neutral; 11-16 mildly emotive or single-sided; 5-10 clearly one-sided or sensational; 0-4 inflammatory or fabricated quotes.',
  'L = Logical Consistency, max 15. Bands: 13-15 coherent; 8-12 minor logical leaps; 4-7 internal contradiction; 0-3 multiple contradictions.',
  'C = Completeness, max 10. Count 5W1H. 6 elements = 9 or 10; 5 = 7; 4 = 6; 3 = 4; fewer than 3 = 1.',
  '',
  'DETERMINISTIC RULES:',
  '- Use fixed band midpoints unless a sub-rule applies.',
  '- Do not improvise scores inside a band. Use the exact fixed values below every time.',
  '- A fixed values: 30-35 band => 32, 20-29 band => 24, 10-19 band => 14, 0-9 band => 4.',
  '- S fixed values: exact Tier 1 reference URL from user => 20, 2+ distinct Tier 1 direct/related sources => 18, exactly 1 Tier 1 direct/related source => 14, Tier 1 partial only => 8, no trusted match => 0.',
  '- The final Normalize node computes Source Quality, Bias, Logical Consistency, and Completeness deterministically where possible. The model should still provide notes, but the code is the source of truth for final score.',
  '- Sensational words deduct 3 points each from B band ceiling, max -9: shocking, outrage, explosive, bombshell, secret, exposes, wake up, they don\'t want you to know, mainstream media won\'t tell you, must share.',
  '- If a Tier 1 source directly contradicts the headline claim, set override_applied=true and force publish_decision=not_reliable.',
  '- If S=0 and A<=10, set override_applied=true and force publish_decision=not_reliable.',
  '- If Tier 1 sources contradict each other 1 vs 1, apply -8 to A and do not let A exceed 27.',
  '- If no matching sources support any claim, A=0 and S=0 unless the topic is clearly personal opinion.',
  '- If MATCHED SOURCES contains relevance_note=primary_source_from_user_reference, treat that URL as the primary Tier 1 evidence anchor.',
  '- If the trusted original source anchor supports the article and no contradiction is found, do not downgrade factual accuracy just because other sources are missing.',
  '- If two rules conflict, the lower score wins.',
  '',
  'PUBLISH DECISION:',
  '- safe_to_publish if trust_score >= 75 AND A >= 25 AND B >= 13.',
  '- needs_review if score is 50-74 OR score >=75 but A<25 or B<13.',
  '- not_reliable if score <50 OR A<15 OR S=0, or any override applies.',
  '',
  'OUTPUT SCHEMA:',
  '{',
  '  "trust_score": 0,',
  '  "publish_decision": "safe_to_publish | needs_review | not_reliable",',
  '  "categories": {',
  '    "factual_accuracy": { "score": 0, "max": 35, "notes": "" },',
  '    "source_quality": { "score": 0, "max": 20, "notes": "" },',
  '    "bias_neutrality": { "score": 0, "max": 20, "notes": "" },',
  '    "logical_consistency": { "score": 0, "max": 15, "notes": "" },',
  '    "completeness": { "score": 0, "max": 10, "notes": "" }',
  '  },',
  '  "matched_sources": [',
  '    { "name": "", "tier": 1, "url": "", "match_type": "direct | related | partial | contradicts" }',
  '  ],',
  '  "flags": [],',
  '  "override_applied": false,',
  '  "override_reason": null',
  '}',
  '',
  'MATCHED SOURCES JSON:',
  matchedSourcesJson,
  '',
  'ARTICLE DRAFT:',
  $json.article_text || '[missing article text]'
].join('\n');


// This second OpenAI call compares the draft against the matched trusted sources.
// It must return strict JSON so the next node can calculate the final trust score safely.
const compareRequest = {
  model: 'gpt-5-mini',
  reasoning: { effort: 'low' },
  text: {
    format: {
      type: 'json_schema',
      name: 'sharedspace_deterministic_score',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          trust_score: { type: 'integer' },
          publish_decision: { type: 'string' },
          categories: {
            type: 'object',
            additionalProperties: false,
            properties: {
              factual_accuracy: { type: 'object', additionalProperties: false, properties: { score: { type: 'integer' }, max: { type: 'integer' }, notes: { type: 'string' } }, required: ['score', 'max', 'notes'] },
              source_quality: { type: 'object', additionalProperties: false, properties: { score: { type: 'integer' }, max: { type: 'integer' }, notes: { type: 'string' } }, required: ['score', 'max', 'notes'] },
              bias_neutrality: { type: 'object', additionalProperties: false, properties: { score: { type: 'integer' }, max: { type: 'integer' }, notes: { type: 'string' } }, required: ['score', 'max', 'notes'] },
              logical_consistency: { type: 'object', additionalProperties: false, properties: { score: { type: 'integer' }, max: { type: 'integer' }, notes: { type: 'string' } }, required: ['score', 'max', 'notes'] },
              completeness: { type: 'object', additionalProperties: false, properties: { score: { type: 'integer' }, max: { type: 'integer' }, notes: { type: 'string' } }, required: ['score', 'max', 'notes'] }
            },
            required: ['factual_accuracy', 'source_quality', 'bias_neutrality', 'logical_consistency', 'completeness']
          },
          matched_sources: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              properties: {
                name: { type: 'string' },
                tier: { type: 'integer' },
                url: { type: 'string' },
                match_type: { type: 'string' }
              },
              required: ['name', 'tier', 'url', 'match_type']
            }
          },
          flags: { type: 'array', items: { type: 'string' } },
          override_applied: { type: 'boolean' },
          override_reason: { type: ['string', 'null'] }
        },
        required: ['trust_score', 'publish_decision', 'categories', 'matched_sources', 'flags', 'override_applied', 'override_reason']
      }
    }
  },
  input: [
    { role: 'system', content: 'Return JSON only. Apply the SharedSpace rubric deterministically using the supplied matched sources and article draft.' },
    { role: 'user', content: rubricPrompt }
  ]
};

return [{ json: { ...$json, matched_sources_json: matchedSourcesJson, compare_prompt: rubricPrompt, compare_request: compareRequest } }];

// Step 5: Normalize the model response into the final result shown in SharedSpace.
// We do not blindly trust the model's final score; we recalculate the score with code below.
const raw = $json.output_text || $json.output?.find((item) => item.type === 'message')?.content?.find((part) => part.type === 'output_text')?.text || '{}';
const cleaned = String(raw).replace(/```json|```/gi, '').trim();
const upstream = $items('Build Compare Request', 0, 0)?.[0]?.json || {};

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  return [{
    json: {
      trust_score: 0,
      summary: 'AI returned invalid JSON.',
      verdict: 'Verification failed. Check the comparison response in n8n.',
      metrics: {
        factual_accuracy: 0,
        source_quality: 0,
        bias_detection: 0,
        logical_consistency: 0,
        completeness: 0
      },
      source_label: 'Invalid AI response',
      matched_articles: upstream.matched_articles || []
    }
  }];
}

const clamp = (value, max) => Math.max(0, Math.min(max, parseInt(value ?? 0, 10) || 0));
const categories = parsed.categories || {};
const matchedSources = Array.isArray(parsed.matched_sources) && parsed.matched_sources.length
  ? parsed.matched_sources
  : (upstream.matched_sources || []);

const sourceKey = (source) => String(source.url || source.name || '').toLowerCase();

// Work out how many trusted sources support the draft.
// Exact Tier 1 reference URLs receive special treatment because they are the original source anchor.
const trustedSources = matchedSources.filter((source) => Number(source.tier || 0) === 1);
const directOrRelated = new Set(trustedSources
  .filter((source) => ['direct', 'related'].includes(String(source.match_type || '').toLowerCase()))
  .map(sourceKey));
const partial = new Set(trustedSources
  .filter((source) => String(source.match_type || '').toLowerCase() === 'partial')
  .map(sourceKey));
const hasTrustedOriginal = trustedSources.some((source) =>
  String(source.relevance_note || '').toLowerCase() === 'primary_source_from_user_reference' &&
  String(source.url || '').split('/').filter(Boolean).length > 2
);
const hasHeadlineContradiction = matchedSources.some((source) => String(source.match_type || '').toLowerCase() === 'contradicts');


// Source Quality is deterministic:
// exact Tier 1 article URL = 20, two or more trusted matches = 18, one trusted match = 14.
const deterministicSourceScore = hasTrustedOriginal
  ? 20
  : directOrRelated.size >= 2
    ? 18
    : directOrRelated.size === 1
      ? 14
      : partial.size > 0
        ? 8
        : 0;


// Factual Accuracy is snapped into fixed bands.
// This prevents tiny model judgement changes from creating random-looking score changes.
const snapFactual = (value) => {
  const score = clamp(value, 35);
  if (score >= 30) return 32;
  if (score >= 20) return 24;
  if (score >= 10) return 14;
  if (score > 0) return 4;
  return 0;
};

const snapLogical = (value) => {
  const score = clamp(value, 15);
  if (score >= 13) return 14;
  if (score >= 8) return 10;
  if (score >= 4) return 5;
  if (score > 0) return 2;
  return 0;
};

const articleText = [upstream.title, upstream.excerpt, upstream.content].filter(Boolean).join(' ').toLowerCase();

// Bias is checked with the sensational-word list from the rubric.
// Neutral articles keep a high bias/neutrality score; clickbait wording gets deducted.
const sensationalWords = ['shocking', 'outrage', 'explosive', 'bombshell', 'secret', 'exposes', 'wake up', "they don't want you to know", "mainstream media won't tell you", 'must share'];
const sensationalHits = sensationalWords.filter((word) => articleText.includes(word));
const bias = Math.max(11, 20 - Math.min(9, sensationalHits.length * 3));

const hasTitle = String(upstream.title || '').trim().length > 0;
const hasSummary = String(upstream.excerpt || '').trim().length > 0;
const hasContent = String(upstream.content || '').trim().length >= 250;
const hasCategory = String(upstream.category || '').trim().length > 0;
const hasSource = String(upstream.source_url || '').trim().length > 0;
const hasDateOrTime = /\b(\d{1,2}\s+(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)|20\d{2}|today|yesterday|monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/i.test(articleText);

// Completeness is calculated from visible article fields and whether a date/time signal is present.
// This makes the 5W1H part explainable instead of relying only on the model's opinion.
const completenessCount = [hasTitle, hasSummary, hasContent, hasCategory, hasSource, hasDateOrTime].filter(Boolean).length;
const completeness = completenessCount >= 6 ? 10 : completenessCount === 5 ? 7 : completenessCount === 4 ? 6 : completenessCount === 3 ? 4 : 1;

let factual = snapFactual(categories.factual_accuracy?.score);
const source = deterministicSourceScore;
let logical = snapLogical(categories.logical_consistency?.score);

if (hasTrustedOriginal && !hasHeadlineContradiction) {
  factual = 32;
  logical = 14;
}


// Final Trust Score. The categories already add up to 100, so we simply add them together.
let trust = factual + source + bias + logical + completeness;
let decision = String(parsed.publish_decision || '').trim();
let overrideApplied = Boolean(parsed.override_applied);
let overrideReason = parsed.override_reason ? String(parsed.override_reason) : null;

if (hasHeadlineContradiction) {
  overrideApplied = true;
  overrideReason = overrideReason || 'A Tier 1 source directly contradicts the article headline or core claim.';
}
if (source === 0 && factual <= 10) {
  overrideApplied = true;
  overrideReason = overrideReason || 'No reliable source match and factual accuracy is too low.';
}

if (overrideApplied || trust < 50 || factual < 15 || source === 0) {
  decision = 'not_reliable';
} else if (trust >= 75 && factual >= 25 && bias >= 13) {
  decision = 'safe_to_publish';
} else {
  decision = 'needs_review';
}

const verdictMap = {
  safe_to_publish: 'Safe to publish. The article is supported by reliable sources and meets the rubric threshold.',
  needs_review: 'Needs review. The article has some support but should be improved before publishing.',
  not_reliable: 'Not reliable. The article does not meet the minimum verification threshold.'
};

const notes = [
  hasTrustedOriginal
    ? 'Exact Tier 1 reference URL detected; factual accuracy and source quality were anchored to the trusted original source unless contradiction was found.'
    : categories.factual_accuracy?.notes,
  hasTrustedOriginal
    ? 'Source quality fixed at 20 because the draft includes an exact Tier 1 reference URL.'
    : `Source quality fixed by matched Tier 1 source count: ${directOrRelated.size} direct/related, ${partial.size} partial.`,
  sensationalHits.length
    ? `Bias score deducted for sensational terms: ${sensationalHits.join(', ')}.`
    : 'Bias score fixed by sensational-language scan: no listed sensational terms found.',
  hasTrustedOriginal
    ? 'Logical consistency fixed at high band because the trusted original source is present and no contradiction was found.'
    : categories.logical_consistency?.notes,
  `Completeness fixed by field/date check: ${completenessCount}/6 elements present.`
].filter(Boolean).join(' ');

return [{
  json: {
    trust_score: trust,
    summary: notes || 'Verification completed using the SharedSpace scoring rubric.',
    verdict: overrideReason ? `${verdictMap[decision]} ${overrideReason}` : verdictMap[decision],
    publish_decision: decision,
    metrics: {
      factual_accuracy: Math.round((factual / 35) * 100),
      source_quality: Math.round((source / 20) * 100),
      bias_detection: Math.round((bias / 20) * 100),
      logical_consistency: Math.round((logical / 15) * 100),
      completeness: Math.round((completeness / 10) * 100)
    },
    rubric_scores: {
      factual_accuracy: factual,
      source_quality: source,
      bias_neutrality: bias,
      logical_consistency: logical,
      completeness
    },
    source_label: matchedSources.length
      ? `Compared against ${matchedSources.length} trusted source${matchedSources.length === 1 ? '' : 's'}.`
      : 'No trusted source match found.',
    matched_sources: matchedSources,
    matched_articles: matchedSources.map((source) => ({
      title: source.title || source.name || '',
      url: source.url || '',
      relevance_note: source.relevance_note || source.match_type || ''
    })),
    flags: [...(parsed.flags || []), ...sensationalHits.map((word) => `sensational_word:${word}`)],
    override_applied: overrideApplied,
    override_reason: overrideReason
  }
}];
